const agentOutput = $input.first().json;
const outputText = agentOutput.output || '';
const steps = agentOutput.intermediateSteps || [];

const MAX_INTENTOS = 2;   // 1 respuesta + 1 reintento. Nunca más.

const SUMMARY_BLOCK = /【summary:[\s\S]*?】/;
const textForDetection = outputText.replace(SUMMARY_BLOCK, '');

const VEHICLE_UNIT_LINE = /(^|\n)\s*[-•*]\s*.+?\b\d{1,3}(?:[.,]\d{3})*\s*km\b/i;
const PRICE_LINE = /\b(ARS|USD)?\s*\$\s*\d{1,3}(?:[.,]\d{3})*(?:[.,]\d+)?/i;
const FINANCING_LINE = /\b(anticipo|financiar|financiaci[oó]n|cuotas)\b/i;

const mentionsVehicles =
  VEHICLE_UNIT_LINE.test(textForDetection) ||
  PRICE_LINE.test(textForDetection) ||
  FINANCING_LINE.test(textForDetection);

const priceStep = steps.find(s =>
  (s.action?.tool || '').toLowerCase().startsWith('get_precios')
);

// --- stock devuelto por la tool ---
let stock = [];
if (priceStep) {
  try {
    const obs = typeof priceStep.observation === 'string'
      ? JSON.parse(priceStep.observation)
      : priceStep.observation;
    stock = Array.isArray(obs) ? obs : (obs?.response || []);
  } catch (e) { stock = []; }
}

// tokens normalizados: sin acentos, sin puntuación interna
// "T-Cross" -> TCROSS | "1.8" -> 18 | "Premier+" -> PREMIER
const tok = s => String(s || '')
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .toUpperCase()
  .split(/\s+/)
  .map(w => w.replace(/[^A-Z0-9]/g, ''))
  .filter(Boolean);

// vocabulario completo de cada fila del stock
const stockVocab = stock.map(v => new Set([
  ...tok(v.MARCA), ...tok(v.MODELO), ...tok(v.VERSION), ...tok(v['AÑO']),
  ...tok(v.TIPO), ...tok(v.COLOR), ...tok(v.TRANSMISION), ...tok(v.COMBUSTIBLE)
]));

const STOPWORDS = new Set(['COLOR','KM','PESOS','USD','ARS','UNIDAD','UNIDADES','DEL','LA','EL','CON']);

const unitLines = textForDetection.split('\n')
  .filter(l => /^\s*[-•*]\s+.+\d[\d.,]*\s*km/i.test(l));

const invented = [];
for (const line of unitLines) {
  const name = line.replace(/^\s*[-•*]\s*/, '').split(',')[0].trim();
  // solo palabras: los números (cilindrada, año, km) se ignoran a propósito
  const words = tok(name).filter(w =>
    /[A-Z]/.test(w) && w.length >= 2 && !STOPWORDS.has(w)
  );
  if (!words.length) continue;   // línea sin nombre legible: no la juzgamos
  const ok = stockVocab.some(vocab => words.every(w => vocab.has(w)));
  if (!ok && !invented.includes(name)) invented.push(name);
}

// --- veredicto ---
let problema = null;
if (mentionsVehicles && !priceStep) {
  problema = { reason: 'vehiculos_sin_tool_precios' };
} else if (stock.length && invented.length) {
  problema = { reason: 'vehiculo_inexistente', invented };
}

if (!problema) {
  return [{ json: { action: 'passthrough', output: outputText, intermediateSteps: steps } }];
}

// $runIndex = cuántas veces ya corrió este nodo en esta ejecución
if ($runIndex < MAX_INTENTOS - 1) {
  return [{ json: { action: 'force_recovery', ...problema, output: outputText, intermediateSteps: steps } }];
}

// reintentos agotados: cortamos el loop y no dejamos pasar datos sin verificar
return [{
  json: {
    action: 'passthrough',
    reason: 'max_reintentos_' + problema.reason,
    invented: problema.invented || [],
    output: 'Dejame confirmar la disponibilidad exacta con un asesor y te respondo en un momento. 🙏',
    intermediateSteps: steps
  }
}];
